export function assertProvenance04Envelope(output,capture){
 for(const name of ['artifacts','validations','relations','decisions','git_objects'])assert.ok(Array.isArray(output?.[name]),'PROV04_ARRAY_'+name);
 const required={artifacts:['artifact_id','operation','path','previous_path','before_sha256','content_sha256','predecessor_id','producer_occurrence_id','patch_ref','status','disposition'],validations:['target_revision','target_sha256','criterion','result','occurrence_id','criterion_state'],decisions:['subject_id','valid_to','revocation_inferred','goal_closed'],git_objects:['repository_id','object_format','oid','object_type','parents','epistemic']};
 for(const [kind,fields]of Object.entries(required))for(const entry of output[kind])for(const field of fields)assert.ok(Object.hasOwn(entry,field),'PROV04_REQUIRED_'+kind+'_'+field);
 const ids=new Set([...capture.occurrences.map(o=>o.id),...capture.records.flatMap(r=>r.raw.payload?.id?[r.raw.payload.id]:[])]);
 for(const name of ['artifacts','validations','decisions','git_objects'])for(const item of output[name]){assert.ok(typeof item.id==='string'&&item.id);assert.ok(!ids.has(item.id),'PROV04_UNIQUE_OUTPUT_ID');ids.add(item.id);}
 for(const [kind,values] of Object.entries(output))for(const item of values){
  const refs=kind==='relations'?item.temporal?.provenance?.evidence_refs:item.evidence_refs;assert.ok(Array.isArray(refs)&&refs.length,'PROV04_NONEMPTY_EVIDENCE');for(const ref of refs)assert.ok(capture.records.some(r=>digest(r.evidence_ref)===digest(ref)),'PROV04_ACQUIRED_EVIDENCE');
  if(kind==='relations'){const validator=oracleAjv.compile({$ref:wireSchema.$id+'#/$defs/Relation'});assert.ok(validator(item),JSON.stringify(validator.errors));assert.ok(ids.has(item.from_id)&&ids.has(item.to_id),'PROV04_RESOLVABLE_ENDPOINTS');}
 }
}
