export function calibrateInsertObservation04(entry,receipt,label){
 const baseline={request:entry.request,response:entry.response,observation:entry.observation};const results=[];
 const variants=[['POSITIVE',null],['PROTECTED_DATABASE_CHANGED',x=>x.observation.inventories[1].rows.find(r=>r.path==='ledger.sqlite').sha256='a'.repeat(64)],['SHM_OMITTED',x=>x.observation.inventories[1].rows=x.observation.inventories[1].rows.filter(r=>r.path!=='ledger.sqlite-shm')],['MAPPED_IDENTITY_WRONG',x=>x.observation.shm_observation.attestations[0].report.metadata.identity='wrong'],['MAPPED_BYTES_TRUNCATED',x=>x.observation.shm_observation.attestations[0].report.bytes_read--],['MAPPED_DIGEST_WRONG',x=>x.observation.shm_observation.attestations[0].report.sha256='b'.repeat(64)],['MAPPED_WRITE_ACCESS',x=>x.observation.shm_observation.attestations[0].report.native_calls.find(c=>c.api==='MapViewOfFile'&&!c.role).access='FILE_MAP_WRITE'],['MAPPING_HANDLE_NOT_CLOSED',x=>x.observation.shm_observation.attestations[0].report.native_calls=x.observation.shm_observation.attestations[0].report.native_calls.filter(c=>c.api!=='CloseHandle')],['DURING_READ_OMITTED',x=>x.observation.inventories=x.observation.inventories.filter(i=>!i.phase.includes('statement.all'))],['WRITER_ADVANCED',x=>x.observation.writer_observation.progress_after.sha256='c'.repeat(64)],['SQL_MUTATION',x=>x.observation.sql_mutations.push({sql:'UPDATE association_version SET revision_no=9'})],['NATIVE_HANDLE_WRITABLE',x=>x.observation.handles[0].readOnly=false],['NATIVE_CALL_UNATTRIBUTED',x=>x.observation.unattributed_boundaries.push({sequence:1})],['WAL_CHANGED',x=>x.observation.native_calls[0].after.find(r=>r.path==='ledger.sqlite-wal').bytes++]];
 const extras=[['EXPLICIT_BOUNDARY_ID_WRONG',x=>x.observation.shm_observation.boundaries[0].boundary_id='wrong'],['EXPLICIT_PHASE_WRONG',x=>x.observation.shm_observation.attestations[0].phase='AFTER'],['PROCESS_ARGUMENT_WRONG',x=>x.observation.shm_observation.attestations[0].process.args[0]='-c'],['HELPER_EXIT_FAILED',x=>x.observation.shm_observation.attestations[0].process.status=1],['PROCESS_ROOT_WRONG',x=>x.observation.shm_observation.attestations[0].report.archive_root=path.dirname(x.observation.root)],['EXECUTED_ROWS_FORGED',x=>x.observation.native_calls.find(c=>c.method==='statement.all').result_rows=[]],['PUBLICATION_CUT_WRONG',x=>x.request.params.published_seq++],['FIRST_INSERT_COUNT_WRONG',x=>{x.observation.writer_observation.progress_before.payload.insert_count=2;x.observation.writer_observation.progress_after.payload.insert_count=2;}],['MISSING_RECORDER_OUTCOME',x=>delete x.observation.outcome]];
 for(const [name,mutate]of [...variants,...extras]){const x=structuredClone(baseline);if(mutate)mutate(x);for(const a of x.observation.shm_observation.attestations){const old=a.attestation_id;a.attestation_id='map04-'+digest({boundary_id:a.boundary_id,helper:a.helper,report:a.report});for(const b of x.observation.shm_observation.boundaries)b.attestation_ids=b.attestation_ids.map(id=>id===old?a.attestation_id:id);}
 let error=null,outcome;try{outcome=assertReadObservation({...x,requireOutcome:true});}catch(e){error={code:e.code,message:e.message,details:e.details};}assert.equal(!!error,!!mutate,label+' '+name);if(error)assert.equal(error.code,'READ_CONTROL_REJECTED',name);results.push({label,name,primary:variants.some(v=>v[0]===name),positive:!mutate,rejected:!!error,error,outcome});}
 (receipt.insert_calibrations??=[]).push({label,request_id:entry.request.request_id,baseline_sha256:digest(baseline),wal_bytes:entry.observation.inventories[0].rows.find(r=>r.path==='ledger.sqlite-wal')?.bytes??null,results});
}
