export async function nativeGraph04Control(request){
  const pointer=JSON.parse(fs.readFileSync(path.join(request.archive,'archive.json'))),snapshot=JSON.parse(fs.readFileSync(path.join(request.archive,'revisions',pointer.revision_id+'.json'))),db=new sqlite.DatabaseSync(path.join(request.archive,'ledger.sqlite'),{readOnly:true});let edges,nodes;
  try{db.exec('BEGIN');edges=db.prepare("SELECT data_json FROM relation_version WHERE json_extract(data_json,'$.from_id')=? AND json_extract(data_json,'$.type')='RESULT_OF' AND commit_seq<=? ORDER BY id").all(request.params.node_id,pointer.published_seq).map(r=>JSON.parse(r.data_json));const ids=[...new Set([request.params.node_id,...edges.map(r=>r.to_id)])];nodes=db.prepare('SELECT data_json FROM event_version WHERE id IN (SELECT value FROM json_each(?)) AND commit_seq<=? ORDER BY id').all(JSON.stringify(ids),pointer.published_seq).map(r=>JSON.parse(r.data_json)).map(e=>({id:e.id,type:'event',revision_id:e.temporal.revision_id,label:e.kind,provenance:e.temporal.provenance}));db.exec('COMMIT');}finally{db.close();}
  const protocol=await import('../../src/archive/protocol.js');return protocol.response(request,{nodes,edges,paths:edges.map(e=>[e.from_id,e.to_id]),visited:nodes.length,truncated:false},protocol.makeReceipt(snapshot,{scope,time,evidence_refs:edges.flatMap(e=>e.temporal.provenance.evidence_refs)}));
}

export function persistGraph04Worker(receipt,request,worker){
 const response=worker.response;receipt.graph_child_observation=worker;(receipt.requests??=[]).push({request,response});assert.equal(validateWire(response,'Response').passed,true);if(response.error?.code==='NOT_IMPLEMENTED')throw Object.assign(new Error(response.error.message),{code:'NOT_IMPLEMENTED'});assert.equal(response.error,null);
 assert.ok(Number.isSafeInteger(worker.worker_pid)&&worker.worker_pid>0);assert.equal(worker.worker_pid,worker.child_process?.pid,'GRAPH04_ACTUAL_WORKER_PID');assert.equal(worker.observation.pid,worker.worker_pid,'GRAPH04_OBSERVER_WORKER_PID');assert.equal(worker.child_process.code,0);assert.equal(worker.child_process.signal,null);assert.ok(/^[a-f0-9]{64}$/.test(worker.child_process.worker.sha256));
 const outcome=assertReadObservation({request,response,observation:worker.observation,requireOutcome:true});assert.deepEqual(outcome,worker.observation.outcome);(receipt.read_only_observations??=[]).push(worker.observation);return response;
}
